import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Plus } from "lucide-react";
import JewelArt from "./JewelArt";
import Reveal from "./Reveal";
import { COLORS, FONT_DISPLAY } from "../constants/theme";
import { money } from "../utils/helpers";
import { fetchProducts, fetchCategories } from "../data/products";

export default function Shop({ filter, setFilter, addToCart }) {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;
    fetchCategories()
      .then((data) => {
        if (!cancelled) setCategories(data);
      })
      .catch(() => {
        if (!cancelled) setCategories([]);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    const categoryId = filter === "All" ? undefined : filter;

    fetchProducts({ categoryId })
      .then((data) => {
        if (!cancelled) setProducts(data.content);
      })
      .catch((err) => {
        if (!cancelled) setError(err.message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [filter]);

  return (
    <section
      id="shop"
      style={{ background: COLORS.surfaceSoft }}
      className="px-4 sm:px-6 md:px-10 py-16 md:py-[100px]"
    >
      <style>{`
        @keyframes shop-badge-in {
          from { opacity: 0; transform: translateY(-4px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .shop-low-stock {
          animation: shop-badge-in 0.3s ease;
        }
        .shop-add-btn {
          transition: transform 0.15s ease, opacity 0.2s ease, background 0.2s ease;
        }
        .shop-add-btn:not(:disabled):hover {
          transform: scale(1.08);
        }
        .shop-add-btn:not(:disabled):active {
          transform: scale(0.92);
        }
        .shop-add-btn:disabled {
          opacity: 0.4;
          cursor: not-allowed;
        }
        .shop-sold-out-tag {
          animation: shop-badge-in 0.3s ease;
        }
      `}</style>
      <div style={{ maxWidth: 1240, margin: "0 auto" }}>
        <Reveal>
          <div className="flex flex-col md:flex-row md:items-end md:justify-between" style={{ gap: 20, marginBottom: 50 }}>
            <div>
              <p style={{ fontSize: 13, letterSpacing: "0.2em", textTransform: "uppercase", color: COLORS.rust, marginBottom: 14 }}>
                The shop
              </p>
              <h2 style={{ fontFamily: FONT_DISPLAY, fontSize: "clamp(28px, 4vw, 44px)" }}>Current pieces</h2>
            </div>
            <div className="mobile-pill-row" style={{ gap: 10 }}>
              <button
                onClick={() => setFilter("All")}
                style={{
                  border: `1px solid ${filter === "All" ? COLORS.surfaceStrong : COLORS.border}`,
                  background: filter === "All" ? COLORS.surfaceStrong : "transparent",
                  color: filter === "All" ? COLORS.textOnStrong : COLORS.text,
                  padding: "12px 18px",
                  fontSize: 13,
                  letterSpacing: "0.03em",
                }}
              >
                All
              </button>
              {categories.map((c) => (
                <button
                  key={c.id}
                  onClick={() => setFilter(c.id)}
                  style={{
                    border: `1px solid ${filter === c.id ? COLORS.surfaceStrong : COLORS.border}`,
                    background: filter === c.id ? COLORS.surfaceStrong : "transparent",
                    color: filter === c.id ? COLORS.textOnStrong : COLORS.text,
                    padding: "9px 18px",
                    fontSize: 13,
                    letterSpacing: "0.03em",
                  }}
                >
                  {c.name}
                </button>
              ))}
            </div>
          </div>
        </Reveal>

        {loading && <p style={{ padding: "20px 0" }}>Loading products…</p>}
        {error && <p style={{ padding: "20px 0", color: "crimson" }}>Couldn't load products: {error}</p>}

        {!loading && !error && (
          <div className="shop-grid grid grid-cols-2 md:grid-cols-4">
            {products.map((p, i) => {
              const stockQuantity = typeof p.stockQuantity === "number" ? p.stockQuantity : Infinity;
              const outOfStock = stockQuantity <= 0;
              const lowStock = !outOfStock && stockQuantity <= 5;

              return (
                <Reveal key={p.id} delay={(i % 4) * 60}>
                  <Link
                    to={`/product/${p.id}`}
                    style={{
                      background: COLORS.surfaceCard,
                      border: `1px solid ${COLORS.border}`,
                      display: "flex",
                      flexDirection: "column",
                      height: "100%",
                      textDecoration: "none",
                      color: "inherit",
                    }}
                  >
                    <div
                      style={{
                        aspectRatio: "1 / 1",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        borderBottom: `1px solid ${COLORS.border}`,
                        position: "relative",
                        overflow: "hidden",
                      }}
                    >
                      {p.imageUrl && p.imageUrl.length > 0 ? (
                        <img
                          src={p.imageUrl[0]}
                          alt={p.name}
                          style={{
                            width: "100%",
                            height: "100%",
                            objectFit: "cover",
                            opacity: outOfStock ? 0.55 : 1,
                          }}
                        />
                      ) : (
                        <JewelArt type={p.art} style={{ width: "42%", color: COLORS.verdigris, opacity: outOfStock ? 0.55 : 1 }} />
                      )}
                      <span
                        style={{
                          position: "absolute",
                          top: 10,
                          left: 10,
                          fontSize: 10.5,
                          letterSpacing: "0.1em",
                          textTransform: "uppercase",
                          color: COLORS.rust,
                        }}
                      >
                        {p.categoryName}
                      </span>
                      {outOfStock && (
                        <span
                          className="shop-sold-out-tag"
                          style={{
                            position: "absolute",
                            top: 10,
                            right: 10,
                            fontSize: 10,
                            letterSpacing: "0.08em",
                            textTransform: "uppercase",
                            color: "#fff",
                            background: "#c0392b",
                            padding: "3px 8px",
                            borderRadius: 4,
                          }}
                        >
                          Sold out
                        </span>
                      )}
                    </div>
                    <div style={{ padding: "14px 14px 16px", display: "flex", flexDirection: "column", flex: 1 }}>
                      <h4 style={{ fontFamily: FONT_DISPLAY, fontSize: "clamp(15px, 4vw, 18px)", marginBottom: 4 }}>
                        {p.name}
                      </h4>
                      <p style={{ fontSize: 12.5, color: COLORS.textSoft, marginBottom: lowStock ? 4 : 14 }}>{p.material}</p>
                      {lowStock && (
                        <p className="shop-low-stock" style={{ fontSize: 11, color: COLORS.rust, marginBottom: 10 }}>
                          Only {stockQuantity} left
                        </p>
                      )}
                      <div className="flex items-center justify-between" style={{ marginTop: "auto" }}>
                        <span style={{ fontSize: 15 }}>{money(p.price)}</span>
                        <button
                          onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            if (outOfStock) return;
                            addToCart(p);
                          }}
                          disabled={outOfStock}
                          aria-label={outOfStock ? `${p.name} is out of stock` : `Add ${p.name} to cart`}
                          className="mobile-touch-target shop-add-btn"
                          style={{
                            width: 40,
                            height: 40,
                            minWidth: 40,
                            borderRadius: "50%",
                            background: outOfStock ? COLORS.surfaceMuted : COLORS.surfaceStrong,
                            color: outOfStock ? COLORS.textFaint : COLORS.textOnStrong,
                            border: "none",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                          }}
                        >
                          <Plus size={15} />
                        </button>
                      </div>
                    </div>
                  </Link>
                </Reveal>
              );
            })}
          </div>
        )}
      </div>
    </section>
  );
}
